static class ProtocolTests {
 static int count;static List<string> passed=new List<string>();static string root,evidence;
 static void Check(bool b,string name){if(!b)throw new Exception(name);count++;passed.Add(name);}
 static Dictionary<string,object> Parse(byte[] b){return Store.Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(b));}
 static byte[] Bytes(string p){return File.ReadAllBytes(p);}
 static TaskOperation New(string name){return new TaskOperation(Path.Combine(root,"tasks"),"isolated-machine",name,true);}
 static string Package(TaskOperation task){string dir=Path.Combine(root,"packages",task.RunId+"-"+task.Attempt);Directory.CreateDirectory(dir);foreach(var p in Directory.GetFiles(evidence,"response_*.bin"))File.Copy(p,Path.Combine(dir,Path.GetFileName(p)));var m=Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(evidence,"result.json")));m["task_run_id"]=task.RunId;m["run_id"]=Path.GetFileName(dir);m["success"]=true;m["received_blocks"]=11;m["crc_valid"]=true;DurableFile.Json(Path.Combine(dir,"manifest.json"),m,false);ZipFile.CreateFromDirectory(dir,dir+".zip");return dir;}
 static byte[] Last(TaskOperation task){return Bytes(task.Events().Last());}
 public static int Main(string[] args){try{if(args.Length<2)throw new ArgumentException("test root and saved evidence directory, or --synthetic, required");root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);evidence=args[1]=="--synthetic"?Synthetic():Path.GetFullPath(args[1]);bool noTarget=false;try{Target.Validate();}catch(Preconditions){noTarget=true;}Check(noTarget,"无授权目标配置时禁止硬件采集");
  var receiver=new MockReceiver();var normal=New("normal-task-0001");normal.StartAttempt();Check(normal.Sequence==1&&File.Exists(normal.Events()[0]),"开始事件先落盘");normal.Progress("读取已经保存的离线证据，不连接设备");normal.Complete(Package(normal));var end=Parse(Last(normal));Check(Convert.ToString(end["event_kind"])=="snapshot"&&!end.ContainsKey("receiver_upgrades"),"完成使用业务快照且无伪造升级字段");Check(Convert.ToString(end["source"])=="grayeye"&&Convert.ToInt32(end["task_protocol"])==1,"独立来源及任务协议标识");Check(((Dictionary<string,object>)end["collection"])["completion_verified"].Equals(true),"采集完成带独立证据");
  foreach(var p in normal.Events())receiver.Receive(Bytes(p));Check(receiver.MainRows==1&&receiver.ErrorRows==0,"正常完成只进入模拟主表");
  var failure=New("recover-task-0002");failure.StartAttempt();failure.Failed(null,"automation","receiver_read","模拟断网");foreach(var p in failure.Events())receiver.Receive(Bytes(p));Check(receiver.ErrorRows==1&&receiver.MainRows==1,"自动异常进入模拟异常表");int before=failure.Sequence;string id=failure.RunId;var retry=new TaskOperation(Path.Combine(root,"tasks"),"isolated-machine",id,true);retry.StartAttempt();Check(retry.RunId==id&&retry.Attempt==2&&retry.Sequence==before+1,"重启后重试保持任务ID且序号递增");retry.Complete(Package(retry));foreach(var p in retry.Events())receiver.Receive(Bytes(p));Check(receiver.MainRows==2&&receiver.ErrorRows==1,"异常后恢复同任务同时保留两表");Check(receiver.Exceptions(id)==1,"重复补传不重复异常计数");
  int main=receiver.MainRows,errors=receiver.ErrorRows;var human=New("human-task-0003");human.StartAttempt();human.Failed(null,"human","user_stop","人工停止");foreach(var p in human.Events())receiver.Receive(Bytes(p));Check(receiver.MainRows==main&&receiver.ErrorRows==errors,"人工停止不算自动故障");Check(Convert.ToString(Parse(Last(human))["origin"])=="human","人工停止保留human来源");var unknown=New("unknown-task-0004");unknown.StartAttempt();unknown.Failed(null,"unknown","unclassified","来源未知");foreach(var p in unknown.Events())receiver.Receive(Bytes(p));Check(receiver.ErrorRows==errors,"未知来源不算自动故障");
  var next=New("separate-task-0005");next.StartAttempt();next.Log("ONLY_TASK_FIVE");next.Complete(Package(next));foreach(var p in next.Events())receiver.Receive(Bytes(p));Check(receiver.MainRows==main+1,"同机同设备同日不同任务不合并");Check(next.RunId!=normal.RunId,"新操作生成独立任务身份");Check(!Convert.ToString(Parse(Last(normal))["content"]).Contains("ONLY_TASK_FIVE"),"任务正文不混入其他任务日志");Check(retry.Events().Select(p=>Convert.ToString(Parse(Bytes(p))["event_id"])).Distinct().Count()==retry.Sequence,"同任务各事件ID唯一");
  var snap=(Dictionary<string,object>)Parse(Last(normal))["device_snapshot"];Check(snap["receiver_version"]==null&&snap["receiver_model"]==null,"未读取版本及型号明确留空");
  var incomplete=New("incomplete-task-0007");incomplete.StartAttempt();string incompleteDir=Package(incomplete);var incompleteManifest=Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(incompleteDir,"manifest.json")));incompleteManifest["received_blocks"]=10;DurableFile.Json(Path.Combine(incompleteDir,"manifest.json"),incompleteManifest,true);bool rejectedIncomplete=false;try{incomplete.Complete(incompleteDir);}catch(IOException){rejectedIncomplete=true;}Check(rejectedIncomplete,"十段数据不能生成完成事件");incomplete.Failed(null,"automation","qualification","未满足完成依据");
  var reversed=new MockReceiver();foreach(var p in retry.Events().Reverse())reversed.Receive(Bytes(p));Check(reversed.MainRows==1&&reversed.ErrorRows==1,"乱序恢复仍保留完成和真实自动异常");var duplicate=reversed.Receive(Last(retry));Check((bool)duplicate["dedup"]&&reversed.MainRows==1&&reversed.ErrorRows==1,"重复发送幂等");var changed=Parse(Last(retry));changed["content"]="改变原件";bool conflict=false;try{reversed.Receive(Encoding.UTF8.GetBytes(Store.Json.Serialize(changed)));}catch(IOException){conflict=true;}Check(conflict,"同ID不同JSON拒绝冲突");
  bool blocked=false;try{Upload.EnsureLive(Last(normal));}catch(IOException){blocked=true;}Check(blocked,"模拟事件禁止真实上传");
  var recover=New("crash-task-0006");recover.StartAttempt();TaskOperation.RecoverAt(Path.Combine(root,"tasks"),"isolated-machine",true);var restored=new TaskOperation(Path.Combine(root,"tasks"),"isolated-machine",recover.RunId,true);Check(restored.Status=="interrupted"&&Convert.ToString(Parse(Last(restored))["origin"])=="unknown","异常退出恢复只标来源未知");int sequence=restored.Sequence;TaskOperation.RecoverAt(Path.Combine(root,"tasks"),"isolated-machine",true);Check(new TaskOperation(Path.Combine(root,"tasks"),"isolated-machine",recover.RunId,true).Sequence==sequence,"再次启动不重复中断事件");
  string[] originals=Directory.GetFiles(Path.Combine(root,"tasks"),"*.json",SearchOption.AllDirectories).Where(p=>p.Contains(Path.DirectorySeparatorChar+"events"+Path.DirectorySeparatorChar)).ToArray();var hashes=originals.ToDictionary(p=>p,p=>Store.Hash(Bytes(p)));int attempts=0;string offline=TaskDelivery.Flush(Path.Combine(root,"tasks"),b=>{attempts++;throw new IOException("模拟离线");},false);Check(offline.Contains("失败任务=")&&attempts>0,"断网保留未接受事件");Check(!Directory.GetFiles(Path.Combine(root,"tasks"),"*.receipt",SearchOption.AllDirectories).Any(),"无持久回执不落接受标记");
  var delivered=new MockReceiver();string drained=TaskDelivery.Flush(Path.Combine(root,"tasks"),delivered.Receive,false);Check(originals.All(p=>File.Exists(TaskDelivery.ReceiptPath(Path.GetDirectoryName(Path.GetDirectoryName(p)),p))),"恢复网络补传每个事件并分别落回执");Check(originals.All(p=>Store.Hash(Bytes(p))==hashes[p]),"断网重试JSON字节完全不变");Check(drained.Contains("失败任务=0"),"积压事件全部补传");int calls=0;TaskDelivery.Flush(Path.Combine(root,"tasks"),b=>{calls++;return delivered.Receive(b);},false);Check(calls==0,"已接收事件常规补传不重复发送");
  string queued=TaskDelivery.Describe(delivered.Receive(Last(retry)));Check(queued.Contains("queued")&&!queued.Contains("两表同步完成"),"HTTP持久接收不冒充两表同步");delivered.Synced=true;string refreshed=TaskDelivery.Flush(Path.Combine(root,"tasks"),delivered.Receive,true);Check(refreshed.Contains("失败任务=0"),"同原事件查询刷新同步回执");Check(TaskDelivery.Describe(delivered.Receive(Last(retry))).Contains("两表同步完成"),"两表分别synced才报告两表同步完成");Check(TaskDelivery.Describe(delivered.Receive(Last(normal))).Contains("另一表不适用"),"无异常时明确异常表不适用");
  var invalid=delivered.Receive(Last(normal));invalid["task_run_id"]="wrong-task";bool bad=false;try{TaskDelivery.ValidateReply(Last(normal),invalid);}catch(IOException){bad=true;}Check(bad,"拒绝错误任务回执");invalid=delivered.Receive(Last(normal));invalid["durable"]=false;bad=false;try{TaskDelivery.ValidateReply(Last(normal),invalid);}catch(IOException){bad=true;}Check(bad,"拒绝未持久保存回执");
  string normalReceipt=TaskDelivery.ReceiptPath(normal.Folder,normal.Events().Last());var normalSaved=Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(normalReceipt));var normalReply=(Dictionary<string,object>)normalSaved["server_reply"];((Dictionary<string,object>)normalReply["sync"])["success"]="queued";DurableFile.Json(normalReceipt,normalSaved,true);Check(TaskDelivery.Summary(Path.Combine(root,"tasks")).Contains("待同步=1"),"汇总保留其他任务待同步状态，不被最后成功覆盖");
  var mixed=delivered.Receive(Last(retry));((Dictionary<string,object>)mixed["sync"])["success"]="failed";Check(TaskDelivery.Describe(mixed).Contains("failed")&&!TaskDelivery.Describe(mixed).Contains("两表同步完成"),"一表同步失败不能冒充两表完成");
  using(var server=new LoopbackReceiver(new MockReceiver())){var reply=Upload.Exchange(server.Uri,"isolated-test-key",Last(normal),true);Check(server.HeaderVerified,"本机HTTP隔离验证X-Upload-Key及POST路径");Check((bool)reply["durable"],"本机HTTP发送与回执解析通过");Check(server.Original.SequenceEqual(Last(normal)),"HTTP发送原始JSON字节不重新序列化");}
  bool externalBlocked=false;try{Upload.Exchange(new Uri("https://example.com/api/huidu/log"),"test",Last(normal),true);}catch(IOException){externalBlocked=true;}Check(externalBlocked,"隔离测试禁止外部网络地址");
  var receiptFile=TaskDelivery.ReceiptPath(normal.Folder,normal.Events()[0]);var originalEvent=normal.Events()[0];File.AppendAllText(originalEvent," ");bool mutationBlocked=false;try{TaskDelivery.Flush(Path.Combine(root,"tasks"),delivered.Receive,false);}catch(IOException){mutationBlocked=true;}Check(mutationBlocked,"原件被篡改时停止补传");Check(File.Exists(receiptFile),"原件与回执独立保存");
  var report=new{success=true,checks=count,passed=passed,device_operations=0,production_network_operations=0,production_feishu_writes=0,receiver="isolated in-memory mock plus loopback HTTP, not production receiver",limitation="灰eye接收端实际路由及真实飞书同步仍待两端联调"};DurableFile.Json(Path.Combine(root,"result.json"),report,false);Console.WriteLine(Store.Json.Serialize(report));return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static string Synthetic(){string dir=Path.Combine(root,"synthetic-fixture");Directory.CreateDirectory(dir);int n=0;foreach(var key in new[]{"010000","020000","030000"}.Concat(Enumerable.Range(0,8).Select(i=>"04000"+i))){var raw=new byte[533];for(int i=0;i<7;i++)raw[i]=85;raw[7]=213;raw[8]=3;raw[9]=1;for(int i=0;i<3;i++)raw[12+i]=Convert.ToByte(key.Substring(i*2,2),16);raw[15]=2;for(int i=17;i<529;i++)raw[i]=(byte)((i+n)%256);Array.Copy(BitConverter.GetBytes(Collect.Crc(raw)),0,raw,529,4);File.WriteAllBytes(Path.Combine(dir,"response_"+(n++).ToString("D2")+".bin"),raw);}DurableFile.Json(Path.Combine(dir,"result.json"),new{success=true,received_blocks=11,crc_valid=true,simulation=true},false);return dir;}
 sealed class MockReceiver {
  readonly Dictionary<string,List<Dictionary<string,object>>> tasks=new Dictionary<string,List<Dictionary<string,object>>>();readonly Dictionary<string,string> originals=new Dictionary<string,string>();public bool Synced;
  public int MainRows {get{return tasks.Values.Count(es=>es.Any(Qualifies));}}
  public int ErrorRows {get{return tasks.Values.Count(es=>es.Any(IsAuto));}}
  static bool IsAuto(Dictionary<string,object> e){return Convert.ToString(e["event_kind"])=="exception"&&Convert.ToString(e["origin"])=="automation";}
  public int Exceptions(string id){return tasks[id].Count(IsAuto);}
  static bool Qualifies(Dictionary<string,object> e){if(!e.ContainsKey("collection"))return false;var c=(Dictionary<string,object>)e["collection"];if(!(bool)c["completion_verified"])return false;var zip=Convert.FromBase64String(Convert.ToString(c["package_base64"]));if(Store.Hash(zip)!=Convert.ToString(c["package_sha256"]))throw new IOException("package hash");using(var stream=new MemoryStream(zip))using(var archive=new ZipArchive(stream,ZipArchiveMode.Read)){var keys=new HashSet<string>();foreach(var entry in archive.Entries.Where(x=>x.Name.StartsWith("response_")&&x.Name.EndsWith(".bin"))){using(var input=entry.Open())using(var output=new MemoryStream()){input.CopyTo(output);byte[] raw=output.ToArray();Collect.Validate(raw);if(raw.Length==533)keys.Add(BitConverter.ToString(raw,12,3));}}var expected=new[]{"01-00-00","02-00-00","03-00-00"}.Concat(Enumerable.Range(0,8).Select(i=>"04-00-0"+i));if(!keys.SetEquals(expected))throw new IOException("11 distinct blocks required");}return true;}
  public Dictionary<string,object> Receive(byte[] original){var e=Parse(original);string task=Convert.ToString(e["task_run_id"]),eventId=Convert.ToString(e["event_id"]);if(Convert.ToInt32(e["task_protocol"])!=1||Convert.ToString(e["source"])!="grayeye"||e.ContainsKey("receiver_upgrades"))throw new IOException("invalid schema");if(!tasks.ContainsKey(task))tasks[task]=new List<Dictionary<string,object>>();var events=tasks[task];var old=events.FirstOrDefault(x=>Convert.ToString(x["event_id"])==eventId||Convert.ToInt32(x["event_sequence"])==Convert.ToInt32(e["event_sequence"]));bool dedup=old!=null;if(dedup){if(originals[Convert.ToString(old["event_id"])]!=Store.Hash(original))throw new IOException("409 conflict");}else{events.Add(e);originals[eventId]=Store.Hash(original);}bool main=events.Any(Qualifies),fail=events.Any(IsAuto);return new Dictionary<string,object>{{"accepted",true},{"durable",true},{"dedup",dedup},{"task_run_id",task},{"event_id",eventId},{"sync",new Dictionary<string,object>{{"success",main?(Synced?"synced":"queued"):"not-applicable"},{"failure",fail?(Synced?"synced":"queued"):"not-applicable"}}}};}
 }
 sealed class LoopbackReceiver:IDisposable {
  TcpListener listener;Thread thread;public readonly Uri Uri;public bool HeaderVerified;public byte[] Original;Exception error;
  public LoopbackReceiver(MockReceiver receiver){listener=new TcpListener(IPAddress.Loopback,0);listener.Start();Uri=new Uri("http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/api/huidu/log");thread=new Thread(()=>{try{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){stream.ReadTimeout=5000;var header=new List<byte>();while(header.Count<32768){int b=stream.ReadByte();if(b<0)throw new IOException("header closed");header.Add((byte)b);if(header.Count>=4&&Encoding.ASCII.GetString(header.Skip(header.Count-4).ToArray())=="\r\n\r\n")break;}string text=Encoding.ASCII.GetString(header.ToArray());var lines=text.Split(new[]{"\r\n"},StringSplitOptions.None);HeaderVerified=lines[0]=="POST /api/huidu/log HTTP/1.1"&&lines.Any(x=>x.Equals("X-Upload-Key: isolated-test-key",StringComparison.OrdinalIgnoreCase))&&!lines.Any(x=>x.StartsWith("Authorization:",StringComparison.OrdinalIgnoreCase));if(lines.Any(x=>x.StartsWith("Expect:",StringComparison.OrdinalIgnoreCase))){byte[] interim=Encoding.ASCII.GetBytes("HTTP/1.1 100 Continue\r\n\r\n");stream.Write(interim,0,interim.Length);}int length=int.Parse(lines.First(x=>x.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase)).Split(':')[1]);Original=new byte[length];int pos=0;while(pos<length){int n=stream.Read(Original,pos,length-pos);if(n==0)throw new IOException("body closed");pos+=n;}byte[] body=Encoding.UTF8.GetBytes(Store.Json.Serialize(receiver.Receive(Original)));byte[] response=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");stream.Write(response,0,response.Length);stream.Write(body,0,body.Length);}}catch(Exception ex){error=ex;}});thread.IsBackground=true;thread.Start();}
  public void Dispose(){listener.Stop();thread.Join(6000);if(error!=null)throw new Exception("loopback server",error);}
 }
